var DATA = {"mode": "types", "types": ["Image", "Text", "Audio", "Video", "Time series", "3D and sensor"]};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="config"){
  show("Label config","XML describing the labeling UI");
  show("Example",DATA.ex);
}else if(m==="task"){
  show("Task JSON",JSON.stringify(DATA.task).slice(0,140));
}else if(m==="install"){
  show("Install","pip install label-studio");
  show("Start","label-studio start");
  show("Then","open http://localhost:8080");
}else if(m==="docker"){
  show("Run","docker compose up (official compose file)");
  show("Image","heartexlabs/label-studio");
}else if(m==="import"){
  show("Import formats",DATA.fmts.join(", "));
  show("Via","UI upload or the API");
}else if(m==="export"){
  show("Export formats",DATA.fmts.join(", "));
}else if(m==="ml"){
  show("ML backend","model pre-labels, humans correct");
  show("Loop","annotate -> train -> pre-label -> repeat");
}else if(m==="webhook"){
  show("Webhooks","notify external systems on events");
  show("Events","annotation created, project updated");
}else if(m==="review"){
  show("Review","a second annotator verifies");
  show("Agreement",DATA.agree+"% across annotators");
}else if(m==="types"){
  console.log("Data types:");DATA.types.forEach(function(t){console.log("  "+t);});
}else if(m==="project"){
  show("Project",DATA.name);
  show("Tasks",DATA.n);
}else if(m==="cli"){
  show("CLI",DATA.cmd);
}else if(m==="stats"){
  show("Annotated",DATA.done+" / "+DATA.total);
  show("Progress",Math.round(DATA.done/DATA.total*100)+"%");
  show("Remaining",DATA.total-DATA.done);
}else if(m==="sdk"){
  show("SDK","label-studio-sdk (Python)");
  show("Does","projects, tasks, and annotations as code");
}else if(m==="workflow"){
  console.log("Labeling workflow:");DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
